{"columns":[{"label":["variable"],"name":[1],"type":["chr"],"align":["left"]},{"label":["mean"],"name":[2],"type":["dbl"],"align":["right"]},{"label":["sd"],"name":[3],"type":["dbl"],"align":["right"]},{"label":["q2.5"],"name":[4],"type":["dbl"],"align":["right"]},{"label":["q97.5"],"name":[5],"type":["dbl"],"align":["right"]}],"data":[{"1":"diff_mu","2":"-0.536","3":"0.148","4":"-0.817","5":"-0.243"}],"options":{"columns":{"min":{},"max":[10]},"rows":{"min":[10],"max":[10]},"pages":{}}}
  </script>
